-- Additive tables for isolated test calls. No operational order is created.
CREATE TABLE IF NOT EXISTS companies (id CHAR(36) PRIMARY KEY, name VARCHAR(160) NOT NULL, status ENUM('active','blocked') NOT NULL DEFAULT 'active', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS company_members (id CHAR(36) PRIMARY KEY, company_id CHAR(36) NOT NULL, user_id CHAR(36) NOT NULL, role_id CHAR(36) NOT NULL, status ENUM('active','revoked') NOT NULL DEFAULT 'active', UNIQUE KEY uq_company_member(company_id,user_id), FOREIGN KEY(company_id) REFERENCES companies(id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE IF NOT EXISTS company_professionals (company_id CHAR(36) NOT NULL, professional_user_id CHAR(36) NOT NULL, status ENUM('active','revoked') NOT NULL DEFAULT 'active', PRIMARY KEY(company_id,professional_user_id), FOREIGN KEY(company_id) REFERENCES companies(id), FOREIGN KEY(professional_user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS professional_locations (professional_user_id CHAR(36) PRIMARY KEY, latitude DECIMAL(10,7) NOT NULL, longitude DECIMAL(10,7) NOT NULL, accuracy_m DECIMAL(8,2), recorded_at TIMESTAMP NOT NULL, FOREIGN KEY(professional_user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS professional_duty_state (professional_user_id CHAR(36) PRIMARY KEY, on_duty BOOLEAN NOT NULL DEFAULT FALSE, online BOOLEAN NOT NULL DEFAULT FALSE, last_seen_at DATETIME(3) NULL, FOREIGN KEY(professional_user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS pickup_test_calls (id CHAR(36) PRIMARY KEY, company_id CHAR(36) NOT NULL, professional_user_id CHAR(36) NOT NULL, created_by CHAR(36) NOT NULL, status ENUM('pending','accepted','rejected','expired') NOT NULL DEFAULT 'pending', created_at DATETIME(3) NOT NULL, expires_at DATETIME(3) NOT NULL, responded_at DATETIME(3) NULL, FOREIGN KEY(company_id) REFERENCES companies(id), FOREIGN KEY(professional_user_id) REFERENCES users(id), FOREIGN KEY(created_by) REFERENCES users(id), INDEX ix_test_call_professional_status(professional_user_id,status,expires_at), INDEX ix_test_call_expiration(status,expires_at), INDEX ix_test_call_company(company_id,created_at));
CREATE TABLE IF NOT EXISTS pickup_test_call_events (id CHAR(36) PRIMARY KEY, call_id CHAR(36) NOT NULL, actor_user_id CHAR(36) NULL, status ENUM('pending','accepted','rejected','expired') NOT NULL, occurred_at DATETIME(3) NOT NULL, FOREIGN KEY(call_id) REFERENCES pickup_test_calls(id), FOREIGN KEY(actor_user_id) REFERENCES users(id), INDEX ix_test_call_events(call_id,occurred_at));
